/*
    Mandelbrot Pattern Decoration (Pastel, Dual-Tint Revision)
    -----------------------------------------------------------
    This version is adjusted so that neither alternating layer is dark.
    Instead, both layers receive a pastel tone—but with a different tint.
*/

///////////////////////////
// Color & Control Parameters
///////////////////////////
const vec3 u_baseColor       = vec3(10.0, 10.6, 1.0);  // Your tested pastel base.
const vec3 u_colorExp        = vec3(1.0, 1.5, 3.0);    // Nonuniform exponents force hue differences.
const float u_colorMul       = 1.0;
const float u_dMinFactor     = 1.0;
const float u_dMaxFactor     = 1.0;  // (Not very active, as you noted.)

const vec3 u_fogColor        = vec3(0.98, 0.90, 1.0);  // Very light pastel fog.
const float u_fringeMix      = 0.5;   // Removed dark fringe mix.
const float u_highlightBlend = 0.4;   // White highlight blend factor.

const float u_vignetteFactor = 10.0;
const float u_vignetteExp    = 1.0/60.0;

// Tint constants for alternating layers:
const vec3 u_evenTint = vec3(1.7, 1.0, 0.4);      // For one family, no extra tint.
const vec3 u_oddTint  = vec3(1.8, 1.0, 1.0);       // For the other, a different pastel tint.

///////////////////////////
// Main Image Function
///////////////////////////
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec3 col = vec3(0.0);
    #define AA 2
    for (int j = 0; j < AA; j++){
        for (int i = 0; i < AA; i++){

            // Standard anti-aliasing sample:
            vec2 p = (fragCoord + vec2(i, j)/float(AA) - iResolution.xy * 0.5) / iResolution.y;

            // Time-based rotation & slight translation:
            float ttm = cos(sin(iTime/8.0)) * 6.2831;
            p *= mat2(cos(ttm), sin(ttm), -sin(ttm), cos(ttm));
            p -= vec2(cos(iTime/2.0)/2.0, sin(iTime/3.0)/5.0);

            // Zoom and offset:
            float zm = (200.0 + sin(iTime/7.0) * 50.0);
            vec2 cc = vec2(-0.57735 + 0.004, 0.57735) + p/zm;

            // Initialize Mandelbrot iteration (position & derivative):
            vec2 z = vec2(0.0), dz = vec2(0.0);
            const int iter = 128;
            int ik = iter;
            vec3 fog = u_fogColor;
            for (int k = 0; k < iter; k++){
                dz = mat2(z, -z.y, z.x) * dz * 2.0 + vec2(1.0, 0.0);
                z = mat2(z, -z.y, z.x) * z + cc;
                if (dot(z, z) > 1.0/0.005){
                    ik = k;
                    break;
                }
            }

            // A grid mask for additional detail:
            float ln = step(0.0, length(z)/15.5 - 1.0);

            // Compute a distance factor used for smooth coloring:
            float d = sqrt(1.0 / max(length(dz), 0.0001)) * log(dot(z, z));
            d = clamp(d * 50.0, 0.0, 1.0);

            // Determine layer “parity” (alternating factor).
            float dir = mod(float(ik), 2.0) < 0.5 ? -1.0 : 1.0;
            float sh = float(iter - ik) / float(iter);

            // Compute a repeating grid pattern:
            vec2 tuv = z / 320.0;
            float tm = -ttm * sh * sh * 16.0;
            tuv *= mat2(cos(tm), sin(tm), -sin(tm), cos(tm));
            tuv = abs(mod(tuv, 1.0/8.0) - 1.0/16.0);
            float pat = smoothstep(0.0, 1.0/length(dz), length(tuv) - 1.0/32.0);
            pat = min(pat, smoothstep(0.0, 1.0/length(dz), abs(max(tuv.x, tuv.y) - 1.0/16.0) - 0.04/16.0));

            // ───── Compute the base color ─────
            // The original code used max(1.0-pat,1.0-ln), which sometimes drops too low.
            // Here we mix that factor with 1.0 to keep the color from going nearly black.
            vec3 colComputed = pow( min(u_baseColor * min(d * u_dMinFactor, u_dMaxFactor), vec3(1.0)),
                                      u_colorExp) * u_colorMul;
            vec3 baseCol = (sqrt(colComputed) * 0.5 + 0.7)
                           * mix(1.0, max(1.0 - pat, 1.0 - ln), 0.5);

            // ───── Apply alternating tint ─────
            // Here we “reverse” the previous branch: now if (dir < 0) we use the even tint,
            // and otherwise we use the odd tint.
            vec3 altCol = (dir < 0.0) ? baseCol * u_evenTint : baseCol * u_oddTint;
            vec3 lCol = altCol;

            // ───── Add white highlights (pseudo reflection) ─────
            vec3 rd = normalize(vec3(p, 1.0));
            rd = reflect(rd, vec3(0.0, 0.0, -1.0));
            float diff = clamp(dot(z*0.5 + 0.5, rd.xy), 0.0, 1.0) * d;
            lCol += mix(lCol, vec3(1.0) * ln, u_highlightBlend)
                    * diff * diff * 0.5 * (pat * 0.6 + 0.6);

            // (Optionally, swap color channels sometimes for extra variation.)
            if (mod(float(ik), 6.0) < 0.5)
                lCol = lCol.yxz;
            lCol = mix(lCol.xzy, lCol, d / 1.2);

            // Do not apply dark-fringe (u_fringeMix is 0)
            lCol = mix(fog, lCol, sh * d);

            col += min(lCol, vec3(1.0));
        }
    }

    col /= float(AA * AA);

    // Apply a subtle vignette:
    vec2 uv = fragCoord / iResolution.xy;
    col *= pow(u_vignetteFactor * (1.0 - uv.x) * (1.0 - uv.y) * uv.x * uv.y, u_vignetteExp)
           * u_colorMul;

    fragColor = vec4(sqrt(max(col, vec3(0.0))), 1.0);
}
